"""Kitchen Sink page: UndoView and UndoStack: a shopping list whose additions and removals
can be undone and redone (Push, Undo, Redo; click a line of the history to go back to it),
and a TextBox's own undo history shown by a second UndoView (its Editor)."""

from vp6 import *


class pgUndo(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Undo history'
        self.Width = 640
        self.Height = 440
        self.lblList = Label(self, Caption='Shopping list:', Left=16, Top=16, Width=180, Height=22,
                             TabIndex=1)
        self.lstItems = ListBox(self, Left=16, Top=40, Width=180, Height=200, TabIndex=2)
        self.txtItem = TextBox(self, Text='Apples', Left=16, Top=248, Width=180, Height=25,
                               TabIndex=3)
        self.cmdAdd = CommandButton(self, Caption='&Add', Left=16, Top=280, Width=88, Height=32,
                                    TabIndex=4)
        self.cmdRemove = CommandButton(self, Caption='&Remove', Left=108, Top=280, Width=88,
                                       Height=32, TabIndex=5)
        self.cmdUndo = CommandButton(self, Caption='&Undo', Left=16, Top=320, Width=88, Height=32,
                                     Enabled=False, TabIndex=6)
        self.cmdRedo = CommandButton(self, Caption='R&edo', Left=108, Top=320, Width=88, Height=32,
                                     Enabled=False, TabIndex=7)
        self.lblHistory = Label(self, Caption='Its history (an UndoView):', Left=210, Top=16,
                                Width=200, Height=22, TabIndex=8)
        self.undList = UndoView(self, Left=210, Top=40, Width=200, Height=272,
                                EmptyLabel='(the empty list)', TabIndex=9)
        self.lblStatus = Label(self, Caption='', Left=16, Top=364, Width=394, Height=60,
                               WordWrap=True, TabIndex=10)
        self.lblNotes = Label(self, Caption='Type here:', Left=424, Top=16, Width=200, Height=22,
                              TabIndex=11)
        self.txtNotes = TextBox(self, MultiLine=True, Text='', Left=424, Top=40, Width=200,
                                Height=150, TabIndex=12)
        self.undNotes = UndoView(self, Left=424, Top=198, Width=200, Height=226,
                                 EmptyLabel='(nothing typed)', Editor='txtNotes', TabIndex=13,
                                 ToolTipText="Editor: the TextBox's own undo history")
    # endregion

    def Form_Load(self):
        self.stack: UndoStack = self.undList.Stack  # (Push, Undo, Redo, CanUndo...)

    def cmdAdd_Click(self):
        item = self.txtItem.Text.strip()
        if item:
            # DoCode runs now (and on Redo), UndoCode on Undo: functions, or code as text
            self.stack.Push(f"Add {item}", lambda: self.lstItems.AddItem(item),
                            lambda: self.lstItems.RemoveItem(self.lstItems.ListCount - 1))

    def cmdRemove_Click(self):
        index = self.lstItems.ListIndex
        if index < 0:
            self.lblStatus.Caption = "Choose an item to remove"
            return
        item = self.lstItems.List[index]
        self.stack.Push(f"Remove {item}", f"self.lstItems.RemoveItem({index})",
                        f"self.lstItems.AddItem({item!r}, {index})")

    def cmdUndo_Click(self):
        self.stack.Undo()

    def cmdRedo_Click(self):
        self.stack.Redo()

    def undList_Change(self):
        stack = self.stack
        self.cmdUndo.Enabled, self.cmdRedo.Enabled = stack.CanUndo, stack.CanRedo
        self.lblStatus.Caption = (f"Change: step {stack.Index} of {stack.Count}; Undo would "
                                  f"undo {stack.UndoText or 'nothing'!r}")

    def undNotes_Change(self):
        self.lblNotes.Caption = f"Type here ({self.undNotes.Stack.Count} changes):"


if __name__ == "__main__":
    run(pgUndo)
